// Related concepts are taught beside the command, before the learner operates.
const lessonConnections = {
 '认识终端与 Linux':['用户、目录、系统是三件事','whoami 回答“我以谁的身份操作”，pwd 回答“命令从哪里开始找文件”，uname 回答“运行什么内核”。先确认这三件事，才能判断下一条命令会影响哪里。','whoami → student；pwd → /home/student','pwd 只显示当前位置，不会修改密码，也不检查内存。'],
 '目录定位与路径':['当前目录决定相对路径','cd /etc 后，notes.txt 表示 /etc/notes.txt；/home/student/notes.txt 无论在哪都指向同一个位置。../ 从当前位置退一层。','/etc 是绝对路径；../logs 是相对路径','以 / 开头才是绝对路径。../logs 要依赖当前位置来解释。'],
 '创建目录与文件':['父目录与文件的关系','先有 lab 目录，才能在里面创建 check.txt。创建没有报错只是第一层证据，ls 读回目录内容才确认目标确实存在。','mkdir lab → touch lab/check.txt → ls -l lab','没有输出不等于失败。用 ls 检查创建结果，避免重复操作。'],
 '读取文件与日志':['行数与上下文','tail 从末尾取行，head 从开头取行。日志排查要同时看错误前后的信息；只看到 ERROR 还不能确定原因。','tail -n 20 app.log：读最后 20 行','-n 后的数字是行数；tail 看末尾，head 看开头。'],
 '复制、移动与删除':['源文件与目标文件','cp 产生一个副本，源路径还在；mv 把内容转移到新路径。改配置前先 cp，再读回备份，才有可验证的退路。','cp notes.txt notes.bak：两份文件都存在','cp 通常保留源文件；mv 通常不保留原路径，rm 删除目标。'],
 '用户与权限':['身份决定使用哪一组权限','先用 id 确认身份，再看文件的属主和属组。755 的第一个 7 是属主权限：4+2+1，等于读、写、执行。','755 → rwx / r-x / r-x','755 的属主位是 7，即读、写、执行；目录 x 表示可进入。'],
 '日志搜索与筛选':['过滤不等于修复','grep 从已有日志中找线索，不会更改服务。-n 给匹配行标行号，便于回到原文件读上下文。','grep -n ERROR app.log → 2:ERROR …','-n 显示行号，不删除日志，也不修复错误。'],
 '磁盘与内存巡检':['容量指标要按对象解释','df 的对象是文件系统，du 的对象是文件或目录。free 中的 available 估计还能供新程序使用的内存，不能把缓存直接当成泄漏。','df -h → 挂载点容量；du -sh /var/log → 目录占用','df 看文件系统容量，du 汇总文件或目录占用，两者统计范围不同。'],
 '进程与 CPU':['PID 与服务名不是同一个概念','服务可能启动多个进程。PID 是某个进程的编号，ps 是快照；找到高 CPU 进程后还要结合日志和持续时间判断。','kill -0 240：检查存在性与发信号权限','信号 0 不终止进程；它用于检查进程是否存在及权限。'],
 '计网入门：地址、端口与分层':['地址负责找位置，端口区分通信端点','把主机想成一栋楼，IP 像楼的地址，端口像入口编号。MAC 用于当前链路的下一跳，不能替代跨网络的 IP 路由。','10.0.0.20:80 → 主机地址 + 服务端口','IP 用于主机寻址，端口帮助区分通信端点。'],
 'IPv4、子网掩码与网关':['前缀决定网络部分','/24 表示前 24 位是网络前缀，掩码为 255.255.255.0。10.0.0.10 与 10.0.0.20 在同一 /24，10.0.1.20 在另一个 /24；最终仍按路由表选择下一跳。','10.0.0.10/24 → 网络 10.0.0.0/24','/24 的掩码为 255.255.255.0。'],
 'DNS：域名怎样变成 IP':['解析成功与业务成功分开验证','DNS 只回答域名对应什么记录。获得 IP 后，仍需建立连接并请求应用。缓存还可能让客户端暂时拿到旧地址。','dig web.lab.test A +short → 10.0.0.20','正确的 DNS 结果只证明解析这一环，还要检查连接和应用响应。'],
 'TCP、UDP 与三次握手':['监听与建立连接是不同状态','LISTEN 表示服务在等连接；ESTAB 表示某条 TCP 连接已建立。TCP 握手先请求同步，再回应同步和确认，最后确认；UDP 不使用这套握手。','SYN → SYN+ACK → ACK','TCP 三次握手的常见顺序是 SYN、SYN+ACK、ACK。'],
 'HTTP、HTTPS 与请求链路':['状态码是应用层证据','收到 404 说明已经获得 HTTP 响应，应查请求路径和应用路由。HTTPS 的 TLS 保护传输，但仍可能返回 404 或 500。','DNS → TCP → TLS → HTTP（常见 HTTPS over TCP）','HTTP 404 是应用层响应，不能据此说从未通信或 DNS 必然故障。'],
 '网络排查：按层收集证据':['每条命令只覆盖一段链路','ip 看接口和路由，dig 看解析，ss 看本机套接字，curl 看请求。把证据拼起来才能缩小范围；单个 ping 不包含所有这些检查。','接口 → 路由 → DNS → 端口 → HTTP','ping 主要验证相关 ICMP 可达性，不能替代 DNS、端口与业务验收。'],
 '网络地址与路由':['网关是下一跳，不是目标服务','ip route 显示出口规则；ping 网关只是探测到这个下一跳。网站还需要解析、服务监听和应用响应。','default via 10.0.0.1：默认下一跳','ping 成功不能证明网站业务正常。'],
 '端口与 HTTP 验证':['从监听到请求，再到业务','ss -lnt 的 l/n/t 分别表示监听、数字显示、TCP。curl -I 只检查这次 HTTP 响应头，健康接口再提供应用层证据。','ss -lnt → :80；curl -I … → 200 OK','ss -lnt 查看监听中的 TCP 端口。'],
 '变量与输出':['赋值、展开、导出是三步','ENV=lab 保存值，$ENV 读取值，export 让子进程也能获得它。等号两边不能有空格，否则 Shell 会把它拆成不同单词。','export ENV=lab → echo "$ENV" → lab','Shell 赋值写成 ENV=lab，不在等号两侧加空格。'],
 '管道与文本组合':['输出可以接命令，也可以写文件','| 把标准输出交给下个命令；> 写文件并覆盖；>> 追加到末尾。先明确接收者是程序还是文件，再选择符号。','cat app.log | grep ERROR | wc -l','>> 追加，> 覆盖。两者都不是删除文件。'],
 '第一个 Shell 脚本':['解释器与执行位','bash health.sh 显式让 Bash 读取脚本；./health.sh 直接执行文件，通常要求执行位，并按 shebang 选择解释器。','#!/bin/bash；chmod 755 health.sh；./health.sh','显式用 Bash 运行与直接执行脚本，对执行位和解释器的要求不同。'],
 '条件判断与退出码':['输出文字与退出状态分开看','命令可以没有输出却成功，也可以打印文字后失败。if 使用命令的退出状态；$? 要立即保存，下一条命令会改变它。','if [ -f "$file" ]; then … fi','退出码 0 通常代表成功，if 按退出状态选择分支。'],
 '循环与巡检清单':['自动化从重复检查开始','for 逐项遍历服务，把每个名称交给相同检查。每轮都记录结果和错误，才不会把“脚本跑完”误当成“所有服务正常”。','for service in nginx; do …; done','for 用来遍历项目，本身不会自动修复故障。'],
 'SSH 与远程连接':['身份包含用户与目标主机','用户@主机决定连接对象，主机指纹帮助验证服务器身份。连接成功后再次确认环境，避免在错误机器上变更。','ssh student@10.0.0.20','首次连接要核对目标和主机指纹，不能盲目接受异常指纹。'],
 'systemd 服务管理':['进程状态与业务健康','active 只说明服务管理器认为服务在运行。还需日志、监听端口和应用请求；先观察，再选择 start、reload 或 restart。','status → journalctl → curl','先看状态与日志，保留证据，再判断是否需要改变服务。'],
 '配置检查与变更验证':['语法校验不覆盖业务验收','备份保证能回退，nginx -t 校验配置，curl 验证请求。三者回答不同问题，不能只做其中一个。','备份 → 校验 → 应用变更 → 请求验证','nginx -t 通过只表示配置检查通过，还需服务与业务验证。'],
 '备份与恢复意识':['备份文件与可恢复数据','列出归档只检查内容清单，真正恢复还需解包、核对数据并验证应用。同盘备份不能抵御整块磁盘损坏。','tar -czf … 创建；tar -tzf … 查看内容','备份后必须验证并演练恢复，不只记住文件名。'],
 '定时任务与执行环境':['计划时间与运行环境','cron 五个字段依次是分、时、日、月、星期。任务运行时的 PATH 和工作目录可能与终端不同，所以使用绝对路径并保存日志。','0 2 * * * /home/student/health.sh','0 2 * * * 的分是 0、时是 2，其余字段表示每天，因此是每天 02:00；实际执行还要核对服务器时区。'],
 '部署一个 Web 服务':['软件来源、进程、请求逐层验收','包安装成功不保证服务启动，服务 active 不保证 HTTP 正常。检查来源、安装、服务、请求，把每层证据留下来。','软件源 → 安装 → systemctl → curl','检查软件源是为了确认软件来源与候选版本。'],
 '表、字段与第一条 SELECT':['字段与行分开选择','SELECT 后写要看的列，FROM 后写表；WHERE 决定哪些行。先认识行列，再学筛选，避免把字段名和表名互换。','SELECT name FROM users;','SELECT 查询数据，FROM 指定数据来源，查询本身不修改记录。'],
 'WHERE、排序与 NULL':['过滤、排序、空值有各自语法','WHERE 筛行，ORDER BY 排顺序，LIMIT 限条数。NULL 表示缺失或未知，通常使用 IS NULL 判断，不能用 = NULL。','SELECT * FROM users WHERE status IS NULL;','NULL 使用 IS NULL 或 IS NOT NULL 判断。'],
 '聚合与分组':['从明细到统计','COUNT 统计数量，GROUP BY 按字段把行归组。先想清楚统计所有行还是统计每个分组，再写查询。','SELECT status, COUNT(*) FROM users GROUP BY status;','GROUP BY 按字段值分组，聚合函数为每组计算结果。'],
 'INSERT 与数据验证':['写入之后按唯一标识读回','明确列名和值的对应关系；主键不能重复。INSERT 成功后 SELECT 读回目标行，确认字段值，而不是只看“执行成功”。','INSERT → 按 id SELECT 读回','明确列名能让每个值与目标字段对应，降低表字段顺序变化时写错位置的风险；插入后还要读回验证。'],
 'UPDATE 与精准修改':['WHERE 决定修改范围','先用相同 WHERE 查询对象，再执行 UPDATE，核对影响行数并读回。省略条件可能改变整张表。','先 SELECT … WHERE id = 2，再 UPDATE … WHERE id = 2','WHERE 限定要修改的行，修改之前必须确认影响范围。'],
 'DELETE 与事务回滚':['回滚依赖事务边界','事务内修改尚未提交时可 ROLLBACK；COMMIT 后通常不能用同一个 ROLLBACK 撤销。删除前先查范围，提交前确认结果。','START TRANSACTION → DELETE … WHERE … → ROLLBACK','可回滚的前提包括尚未提交及修改可事务化。'],
 'MySQL 部署流程与预检查':['部署需要恢复目标','磁盘、版本、字符集、连接与备份都影响业务。RPO 是能接受丢失多少时间的数据，RTO 是能接受多久恢复；它们影响备份方案。','容量检查 → 版本确认 → 恢复目标 → 备份方案','预检查用来确认环境与资源，部署不只是安装一个包。'],
 '数据库服务与连接巡检':['进程、连接、查询三层证据','systemctl 看服务，mysqladmin ping 看服务响应，实际 SQL 验证会话和查询。端口通了不保证认证或权限正确。','systemctl → mysqladmin ping → SELECT','数据库巡检还要验证连接、认证与实际查询，不能只看进程。'],
 '容量、连接与慢查询':['指标需要趋势和业务背景','Threads_connected 是当前连接数，慢查询需要结合执行时间、频率和业务路径。记录趋势再定位，单次数字不能代替判断。','SHOW STATUS；SHOW PROCESSLIST；结合日志','慢查询要结合执行计划、索引、数据量与锁等待分析，不能仅靠重启或增加连接数解决。'],
 '执行计划与索引意识':['索引是访问路径，不是万能加速','EXPLAIN 展示优化器选择的访问计划。PRIMARY 和 ALL 分别提示可能使用主键或全表扫描；小表全扫未必慢，索引也有写入成本。','EXPLAIN SELECT * FROM users WHERE id = 1;','EXPLAIN 用于观察查询执行计划，不自动备份或删除数据。'],
 '数据库备份与恢复演练':['一致性、完整性、恢复验证','逻辑备份输出数据与建表语句，事务一致性有引擎和 DDL 限制。先恢复到隔离环境，核对行数、关键记录与业务查询。','导出 → 校验 → 隔离恢复 → 查询验收','恢复应先在隔离测试环境演练，避免直接覆盖生产数据。'],
 '安装与启动 MySQL 测试服务':['可连接之后才开始账户与业务配置','软件包安装、服务启动、认证与最小权限是不同步骤。需要继续安排访问限制、备份和监控，不能把安装当成上线完成。','软件源 → 安装 → 启动 → ping → 认证与权限','安装后还要检查启动、认证、权限、网络限制、备份和监控。'],
 '镜像、容器与端口':['打包对象与运行实例','镜像描述运行环境，容器是启动后的实例。宿主机端口与容器端口可能不同，访问入口要结合发布端口与监听地址判断。','宿主机 8080 → 容器 80','8080→80 表示请求使用宿主机的 8080 端口，转发到容器内的 80 端口；两边端口可以不同。'],
 '容器日志与恢复':['恢复动作应由证据决定','容器在运行不代表应用健康。先看状态和日志，再评估恢复；重启后还要发请求，并处理导致异常的根因。','docker ps → docker logs → 请求验证','容器重启后仍需验证业务响应并分析原因；重启只是可能的恢复动作，不代表故障彻底解决。'],
 'K8s 对象与上下文':['上下文决定命令操作哪个集群','context 组合集群、用户、默认命名空间。Pod 是运行单元，Deployment 管理副本，Service 提供稳定入口；先核对上下文再变更。','kubectl config current-context；-n learning','Deployment 管理应用副本与更新，控制器让实际状态接近期望状态；Service 和 Pod 分别承担入口和运行单元的职责。'],
 'kubectl 观察与诊断':['状态、事件、应用日志分工不同','get 展示概况，describe 提供对象详情和事件，logs 读取已启动容器的输出。调度失败或拉镜像失败时，应用日志可能不存在。','get → describe / Events → logs','Pod 一直 Pending 时，优先用 describe 看 Events 与调度信息，检查资源、节点约束或存储等原因；应用还没启动，日志可能不存在。'],
 '编写 Deployment YAML':['期望状态与控制器','replicas 声明副本数，selector 匹配 Pod 标签，template 定义新 Pod。apply 后由控制器协调实际状态，所以还要 rollout 验证。','selector.matchLabels 与 template.metadata.labels 对应','replicas: 2 声明期望运行两个副本，不保证它们立即就绪；apply 后仍需查询状态。'],
 'Service 与集群访问':['标签是对象之间的连接线','Service selector 匹配 Pod 标签，再通过 targetPort 指向容器端口。ClusterIP 通常供集群内访问，不自动开放公网入口。','Service selector → Pod labels → targetPort','Service 通过标签选择后端；端口和访问类型决定入口范围。'],
 '扩容与滚动更新检查':['副本数不等于可用副本数','scale 改期望副本数，rollout 查看更新是否推进，readiness 决定是否接收流量。检查 Ready 与请求，不能只看命令返回成功。','scale → rollout status → Ready → 请求','扩容或更新后检查实际就绪状态与业务，而非只看提交成功。'],
 'Pod 故障排查与复盘':['错误阶段决定排查方向','Pending 关注调度，ImagePullBackOff 关注镜像拉取，CrashLoopBackOff 关注容器退出。先确认阶段，再读对应事件和日志。','ImagePullBackOff → describe / Events → 镜像与凭据','镜像拉取失败应优先看 Events 和镜像配置，容器日志可能不存在。'],
 '部署前检查清单':['应用回退与数据回退不是一回事','旧应用可能不兼容新的数据库结构。发布前评估前后版本、配置和数据兼容，并验证备份及回退路径。','版本 → 环境 → 依赖 → 备份 → 回退 → 验收标准','回退方案让失败时能按已验证路径恢复，但必须考虑数据兼容。'],
 '发布验收与日常巡检':['从技术状态走到业务路径','进程在、端口开、HTTP 200、依赖可用，都只是各层证据。最终按经过批准的核心业务路径和监控指标验收。','进程 → 端口 → HTTP → 数据依赖 → 业务','完整验收应覆盖服务、请求、依赖和业务路径。'],
 '故障恢复、回滚与复盘':['恢复业务与修复根因','恢复优先让业务重新可用，复盘再把时间线、根因和防复发措施落实。留证能帮助判断恢复动作有没有效果。','影响 → 证据 → 定位 → 恢复 → 验证 → 复盘','恢复后要验证、复盘并跟进防复发措施，不能直接删除日志。']
};
function connectionFor(c){return lessonConnections[c.title]||['先观察，再行动，再验证',c.concept,c.steps.map(s=>s.cmd).join(' → '),c.concept];}
function relatedHTML(c){const [title,meaning,example]=connectionFor(c);const prev=!lab&&c.id>0?courses[c.id-1]:null;return `<section class="related-knowledge"><div class="eyebrow">把知识连起来</div><h3>${esc(title)}</h3><p>${esc(meaning)}</p><pre>${esc(example)}</pre>${prev?`<div class="knowledge-bridge"><b>接着上一关：${esc(prev.title)}</b><span>沿用“先确认对象，再操作，最后读回结果”的习惯。这一关把证据推进到「${esc(c.steps.at(-1).task)}」。</span><button class="text-button" data-action="lesson" data-id="${prev.id}">复习上一关</button></div>`:'<p class="small-note">第一关先建立习惯：每条命令都要知道它检查谁、输出什么、能证明什么。</p>'}</section>`;}
